// Production: exec checkov -d /path/to/terraform --output json --soft-fail
// Mock Checkov JSON output structure:
const ctx=$input.first().json;
const mock=[
  {check_id:'CKV_AWS_58',check_type:'terraform',resource:'aws_s3_bucket.data',check_result:{result:'FAILED'},severity:'HIGH',
   short_description:'Ensure S3 bucket encryption is enabled',guideline:'https://docs.prismacloud.io/en/enterprise-edition/policy-reference/aws-policies/aws-s3-policies/s3-14-data-encrypted-at-rest'},
  {check_id:'CKV_AWS_18',check_type:'terraform',resource:'aws_s3_bucket.logs',check_result:{result:'PASSED'},severity:'MEDIUM',short_description:'Ensure access logging enabled'}
];
const failed=mock.filter(c=>c.check_result.result==='FAILED');
const critical=failed.filter(c=>c.severity==='CRITICAL');
const high=failed.filter(c=>c.severity==='HIGH');
return[{json:{...ctx,checks_run:mock.length,failed_count:failed.length,critical_count:critical.length,
  high_count:high.length,should_fail:critical.length>0||high.length>0,
  failed_checks:failed,scanned_at:new Date().toISOString()}}];

